SELECT issue_key, count(*) AS 스냅샷수, min(snapshot_ts) AS 시작, max(snapshot_ts) AS 끝, max(pulse_score) AS 최고점수
FROM issue_cluster WHERE issue_key LIKE 'demo-%' GROUP BY issue_key;
